{
  "id": "ww-00034",
  "version": "0.1",
  "concept_id": "ww-00034",
  "identity": {
    "name": "BRUTALK",
    "tagline": "No Filters. Just Fluency.",
    "one_line_description": "BRUTALK is a raw, no-nonsense language learning platform that strips away the fluff and delivers real-world fluency through structured classes, expert instructors, and brutal honesty about what it takes to learn a language.",
    "domain": "education",
    "subdomain": "language learning platform",
    "voice": [
      "blunt",
      "bold",
      "energetic",
      "direct",
      "unpolished"
    ],
    "target_audience": "Ambitious adult learners aged 18\u201340 who are frustrated with slow, gamified language apps and want a serious, structured, instructor-led path to real fluency."
  },
  "pages": [
    {
      "slug": "home",
      "title": "Home",
      "role": "landing",
      "goal": "Hit the visitor hard with a brand arrival that feels unmistakable \u2014 bold, raw, and immediately clear about what BRUTALK is and who it's for. Anchor the visitor with a confrontational hero moment, then build trust through proof, offerings, and a final aggressive CTA that pushes them to act.",
      "meta_description": "BRUTALK is the language learning platform for people who are done messing around. Real classes. Real instructors. Real fluency. No filters.",
      "sections": [
        {
          "id": "home-section-1",
          "type": "hero",
          "intent": "Deliver a confrontational, unmistakable arrival moment \u2014 the brand's raw energy should hit before the visitor reads a single word. This section exists to declare what BRUTALK is and to immediately qualify the right visitor while repelling the wrong one.",
          "eyebrow": "Language Learning. Unfiltered.",
          "headline": "Stop Playing Games. Start Speaking.",
          "subheadline": "BRUTALK is the structured language platform for people who want fluency, not points. Real instructors, real classes, real results.",
          "body": null,
          "items": [],
          "ctas": [
            {
              "label": "See All Classes",
              "target_page": "classes"
            },
            {
              "label": "View Pricing",
              "target_page": "pricing"
            }
          ],
          "asset_ideas": [
            {
              "id": "home-section-1-asset-1",
              "kind": "logo",
              "subject": "BRUTALK wordmark \u2014 heavy block letterforms, high-contrast, with a single diagonal slash cutting through the lettering to suggest forward momentum and rule-breaking",
              "purpose": "Establish the brand identity at the hero level with maximum visual impact",
              "quantity": 1,
              "used_by": [
                "home-section-1"
              ]
            }
          ]
        },
        {
          "id": "home-section-2",
          "type": "stats",
          "intent": "Let the numbers feel alive as they enter view \u2014 each figure should land like a punch, reinforcing credibility and scale without softening the brand voice. This section converts skeptics by grounding the bold claims in raw data.",
          "eyebrow": "The Numbers Don't Lie",
          "headline": "Results That Speak for Themselves",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "12,400+",
              "description": "Active learners enrolled across all languages and levels",
              "metadata": {}
            },
            {
              "title": "94%",
              "description": "Of students report measurable conversational progress within 8 weeks",
              "metadata": {}
            },
            {
              "title": "18 Languages",
              "description": "Offered across beginner, intermediate, and advanced tracks",
              "metadata": {}
            },
            {
              "title": "200+ Instructors",
              "description": "Native and near-native speakers with verified teaching credentials",
              "metadata": {}
            }
          ],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "home-section-3",
          "type": "feature_grid",
          "intent": "Staggered reveal as the visitor scrolls \u2014 each card drops in with purpose, making the platform's advantages feel deliberate and earned rather than listed. This section answers the question 'Why BRUTALK over everything else?'",
          "eyebrow": "Why BRUTALK Works",
          "headline": "We Cut Everything That Doesn't Make You Fluent",
          "subheadline": "No streaks. No badges. No filler. Just the mechanics of language acquisition done right.",
          "body": null,
          "items": [
            {
              "title": "Live Instructor Sessions",
              "description": "Every class is taught live by a credentialed native-speaker instructor. No pre-recorded loops. No chatbots.",
              "metadata": {}
            },
            {
              "title": "Structured Progression Tracks",
              "description": "Classes follow a deliberate CEFR-aligned curriculum from A1 to C2 so you always know exactly where you stand.",
              "metadata": {}
            },
            {
              "title": "Small Cohorts, Real Pressure",
              "description": "Classes are capped at 10 students. You will be called on. That's the point.",
              "metadata": {}
            },
            {
              "title": "Weekly Speaking Assessments",
              "description": "Instructors score your spoken output every week. Honest feedback, not encouragement theater.",
              "metadata": {}
            },
            {
              "title": "Flexible Scheduling",
              "description": "Morning, afternoon, and evening slots across time zones. No excuse not to show up.",
              "metadata": {}
            },
            {
              "title": "Community Practice Rooms",
              "description": "Unstructured peer practice sessions between classes to build real conversational reflex.",
              "metadata": {}
            }
          ],
          "ctas": [
            {
              "label": "Explore the Classes",
              "target_page": "classes"
            }
          ],
          "asset_ideas": []
        },
        {
          "id": "home-section-4",
          "type": "testimonial",
          "intent": "A slow ambient warmth that invites the visitor to linger \u2014 real voices from real learners cut through the brand's hard edge with human proof. This section earns emotional trust after the rational case has been made.",
          "eyebrow": "Heard From the Trenches",
          "headline": "People Who Stopped Dabbling and Started Speaking",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "Marta V. \u2014 Spanish \u2192 German, B2",
              "description": "\"I tried three apps and two YouTube channels. BRUTALK was the first thing that actually made me uncomfortable enough to improve. I passed my B2 exam in 14 weeks.\"",
              "metadata": {
                "language": "German",
                "level": "B2"
              }
            },
            {
              "title": "James O. \u2014 English \u2192 Mandarin, HSK 3",
              "description": "\"The small class size means you can't hide. I hated it for the first two weeks. Now I order food in Mandarin every single day.\"",
              "metadata": {
                "language": "Mandarin",
                "level": "HSK 3"
              }
            },
            {
              "title": "Priya S. \u2014 Hindi \u2192 French, B1",
              "description": "\"My instructor gave me feedback that stung. It was exactly what I needed. Six months later I'm living in Lyon and actually surviving.\"",
              "metadata": {
                "language": "French",
                "level": "B1"
              }
            }
          ],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "home-section-5",
          "type": "cta",
          "intent": "A single confident flourish on the close \u2014 the final section should feel like a door being kicked open, not a polite invitation. Push the visitor to commit with urgency and clarity.",
          "eyebrow": "No More Excuses",
          "headline": "Pick a Language. Book a Class. Show Up.",
          "subheadline": "Your next cohort starts this week. Seats are capped. First session is on us.",
          "body": null,
          "items": [],
          "ctas": [
            {
              "label": "Claim Your Free First Class",
              "target_page": "pricing"
            },
            {
              "label": "See the Schedule",
              "target_page": "schedule"
            }
          ],
          "asset_ideas": [
            {
              "id": "home-section-5-asset-1",
              "kind": "pattern",
              "subject": "Repeating raw typographic grid pattern using bold block letterforms of language codes \u2014 ES, FR, DE, ZH, JP, AR \u2014 arranged in a dense, offset brick-like tiling",
              "purpose": "Fill the CTA section background with kinetic brand texture that signals linguistic breadth without using photography",
              "quantity": 1,
              "used_by": [
                "home-section-5"
              ]
            }
          ]
        }
      ]
    },
    {
      "slug": "classes",
      "title": "Classes",
      "role": "overview",
      "goal": "Give the visitor a comprehensive, no-nonsense overview of every language and level available on the platform. Each class card should feel like a direct challenge \u2014 here's what you're signing up for, here's what it demands. Staggered card reveal should make the catalog feel alive and abundant.",
      "meta_description": "Browse BRUTALK's full catalog of live language classes across 18 languages and six CEFR levels. Small cohorts, real instructors, real progress.",
      "sections": [
        {
          "id": "classes-section-1",
          "type": "page_header",
          "intent": "Frame the catalog with the brand's raw directness \u2014 this isn't a menu to browse passively, it's a challenge to pick a language and commit.",
          "eyebrow": "The Full Catalog",
          "headline": "18 Languages. 6 Levels. Zero Filler.",
          "subheadline": "Every class is live, instructor-led, and capped at 10 students. Pick your language. Pick your level. Get in.",
          "body": null,
          "items": [],
          "ctas": [],
          "asset_ideas": [
            {
              "id": "classes-section-1-asset-1",
              "kind": "illustration",
              "subject": "Abstract globe constructed entirely from bold typographic letterforms and language script fragments \u2014 Latin, Cyrillic, Arabic, Hanzi, Hiragana \u2014 arranged in a raw collage style with no smooth gradients",
              "purpose": "Anchor the page header with a visual that signals global language breadth in the brutalist aesthetic",
              "quantity": 1,
              "used_by": [
                "classes-section-1"
              ]
            }
          ]
        },
        {
          "id": "classes-section-2",
          "type": "item_grid",
          "intent": "The core catalog \u2014 each card drops in with staggered energy as the visitor scrolls, making the breadth of offerings feel earned and substantial. Every card must communicate the language, level, pace, and what the student will be able to do by the end.",
          "eyebrow": "Featured Languages",
          "headline": "Choose Your Target Language",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "Spanish \u2014 All Levels",
              "description": "From survival phrases to near-native fluency. The most enrolled language on the platform. 6 active cohorts running this month.",
              "metadata": {
                "levels": "A1\u2013C2",
                "cohorts": "6",
                "session_length": "90 min"
              }
            },
            {
              "title": "Mandarin Chinese \u2014 All Levels",
              "description": "Character recognition, tonal accuracy, and spoken fluency built in parallel. Includes dedicated HSK prep tracks.",
              "metadata": {
                "levels": "A1\u2013C2",
                "cohorts": "4",
                "session_length": "90 min"
              }
            },
            {
              "title": "French \u2014 All Levels",
              "description": "Parisian register and practical spoken French from day one. Grammar is taught in context, never in isolation.",
              "metadata": {
                "levels": "A1\u2013C2",
                "cohorts": "5",
                "session_length": "90 min"
              }
            },
            {
              "title": "German \u2014 All Levels",
              "description": "Structured, rigorous, and deeply satisfying. Case grammar is not avoided \u2014 it's drilled until it becomes reflex.",
              "metadata": {
                "levels": "A1\u2013C2",
                "cohorts": "3",
                "session_length": "90 min"
              }
            },
            {
              "title": "Japanese \u2014 All Levels",
              "description": "Three scripts, two politeness registers, and a curriculum that doesn't pretend any of it is easy.",
              "metadata": {
                "levels": "A1\u2013C2",
                "cohorts": "3",
                "session_length": "90 min"
              }
            },
            {
              "title": "Arabic \u2014 All Levels",
              "description": "Modern Standard Arabic with dialect exposure. Right-to-left script from week one.",
              "metadata": {
                "levels": "A1\u2013C2",
                "cohorts": "2",
                "session_length": "90 min"
              }
            },
            {
              "title": "Portuguese \u2014 All Levels",
              "description": "Brazilian and European tracks available. Pronunciation differences addressed head-on from the start.",
              "metadata": {
                "levels": "A1\u2013C2",
                "cohorts": "2",
                "session_length": "90 min"
              }
            },
            {
              "title": "Korean \u2014 All Levels",
              "description": "Hangul literacy in week one, conversational Korean by week six. K-drama references are not the curriculum.",
              "metadata": {
                "levels": "A1\u2013C2",
                "cohorts": "2",
                "session_length": "90 min"
              }
            }
          ],
          "ctas": [
            {
              "label": "Check the Schedule",
              "target_page": "schedule"
            }
          ],
          "asset_ideas": []
        },
        {
          "id": "classes-section-3",
          "type": "comparison",
          "intent": "A deliberate, almost confrontational stillness \u2014 this section holds the visitor in place and forces a clear-eyed comparison between BRUTALK's approach and the passive, app-based alternatives they've probably already tried and abandoned.",
          "eyebrow": "BRUTALK vs. Everything Else",
          "headline": "This Is What Serious Language Learning Looks Like",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "Live human instructor",
              "description": "BRUTALK: Every session. Apps: Never.",
              "metadata": {
                "brutalk": "Yes",
                "typical_app": "No"
              }
            },
            {
              "title": "Real-time spoken feedback",
              "description": "BRUTALK: Weekly scored assessments. Apps: Auto-graded multiple choice.",
              "metadata": {
                "brutalk": "Yes",
                "typical_app": "No"
              }
            },
            {
              "title": "Cohort accountability",
              "description": "BRUTALK: Max 10 students per class. Apps: Solo, anonymous, no pressure.",
              "metadata": {
                "brutalk": "Yes",
                "typical_app": "No"
              }
            },
            {
              "title": "CEFR-aligned progression",
              "description": "BRUTALK: Structured A1\u2013C2 tracks. Apps: Gamified levels with no external validity.",
              "metadata": {
                "brutalk": "Yes",
                "typical_app": "No"
              }
            },
            {
              "title": "Completion accountability",
              "description": "BRUTALK: Instructors track attendance and flag disengagement. Apps: Your streak breaks silently.",
              "metadata": {
                "brutalk": "Yes",
                "typical_app": "No"
              }
            }
          ],
          "ctas": [],
          "asset_ideas": []
        },
        {
          "id": "classes-section-4",
          "type": "faq",
          "intent": "Neutralize the objections that stop a serious learner from enrolling \u2014 answered bluntly and without corporate softening, consistent with the brand voice.",
          "eyebrow": "Straight Answers",
          "headline": "Questions We Get. Answered Honestly.",
          "subheadline": null,
          "body": null,
          "items": [
            {
              "title": "Do I need any prior knowledge to start?",
              "description": "No. A1 classes start from absolute zero. You don't need to know a single word. But you do need to show up and participate.",
              "metadata": {}
            },
            {
              "title": "What happens if I miss a class?",
              "description": "You'll receive a session summary and access to the instructor's notes. You will not receive a recording. Attendance matters.",
              "metadata": {}
            },
            {
              "title": "How long is each class?",
              "description": "90 minutes per session. Most tracks run two sessions per week. That's three hours of live instruction weekly \u2014 the minimum effective dose.",
              "metadata": {}
            },
            {
              "title": "Can I switch levels mid-track?",
              "description": "Yes, with instructor approval after a brief spoken assessment. We don't let students self-diagnose their level \u2014 that's how people stagnate.",
              "metadata": {}
            },
            {
              "title": "Are classes recorded?",
              "description": "No. This is a deliberate choice. Presence is the product. You learn by doing, not by watching yourself do it later.",
              "metadata": {}
            }
          ],
          "ctas": [
            {
              "label": "See Pricing & Plans",
              "target_page": "pricing"
            }
          ],
          "asset_ideas": [
            {
              "id": "classes-section-4-asset-1",
              "kind": "icon",
              "subject": "Set of six minimalist language-script icons \u2014 each a single bold glyph representing a different writing system (Latin A, Arabic \u0639, Hanzi \u8bed, Hiragana \u3042, Cyrillic \u042f, Hangul \ud55c) rendered in thick strokes on a raw square tile",
              "purpose": "Provide visual anchors for the FAQ and catalog sections to reinforce the multi-language identity without photography",
              "quantity": 1,
              "used_by": [
                "classes-section-4"
              ]
            }
          ]
        },
        {
          "id": "classes-section-5",
          "type": "cta",
          "intent": "Close the classes page with a confident push \u2014 the visitor has seen the catalog, understood the approach, and run out of reasons to delay. Make the next step feel obvious and urgent.",
          "eyebrow": "Ready to Commit?",
          "headline": "Your Cohort Is Forming Right Now.",
          "subheadline": "Seats fill fast. Don't spend another week thinking about it.",
          "body": null,
          "items": [],
          "ctas": [
            {
              "label": "View the Schedule",
              "target_page": "schedule"
            },
            {
              "label": "See Pricing",
              "target_page": "pricing"
            }
          ],
          "asset_ideas": []
        }
      ]
    },
    {
      "slug": "schedule",
      "title": "Schedule",
      "role": "listing",
      "goal": "Give the visitor a clear, scannable, no-excuses view of every upcoming class session across all languages and levels. The schedule should feel like a timetable posted on a wall \u2014 raw, functional, and authoritative. Remove every barrier between the visitor and booking a seat.",
      "meta_description": "Find your next BRUTALK class session. Live language classes running morning, afternoon, and evening across all time zones. Browse by language, level, or date.",
      "sections": [
        {
          "id": "schedule-section-1",
          "type": "page_header",
          "intent": "Set the functional tone of the schedule page \u2014 this is a working tool, not a marketing page. The header should orient the visitor immediately and push them to filter and find their session.",
