/* ============================================================
   BRUTALK — Brutalist Raw Language Learning Platform
   Shared stylesheet
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=VT323&display=swap');

:root {
  --black: #0A0A0A;
  --chalk: #F2F2F2;
  --red: #E8000D;
  --blue: #0000EE;
  --slab: #1E1E1E;
  --yellow: #FFD600;
  --slab-edge: #2E2E2E;

  --font-head: 'Arial Black', 'Arial Bold', Arial, sans-serif;
  --font-body: 'Courier New', Courier, monospace;
  --font-mono: 'VT323', 'Courier New', monospace;

  --container: 1280px;
  --pad-x: 48px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  background: var(--black);
  color: var(--chalk);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: var(--blue); text-decoration: underline; }
a:hover { text-decoration-thickness: 3px; }

img, svg { display: block; max-width: 100%; }

.container {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 var(--pad-x);
}

/* ============================================================
   NAVIGATION
   ============================================================ */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--black);
  border-bottom: 2px solid var(--chalk);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  padding: 0 var(--pad-x);
  max-width: 100%;
}
.nav-brand {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 22px;
  letter-spacing: -0.02em;
  color: var(--chalk);
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.nav-brand .slash {
  display: inline-block;
  color: var(--red);
  transform: skewX(-18deg);
  font-weight: 900;
}
.nav-links {
  display: flex;
  gap: 24px;
  list-style: none;
}
.nav-links a {
  font-family: var(--font-mono);
  font-size: 16px;
  color: var(--chalk);
  text-decoration: none;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 4px;
  border-bottom: 2px solid transparent;
  transition: color 80ms linear, border-color 80ms linear;
}
.nav-links a:hover { color: var(--red); border-bottom-color: var(--red); }
.nav-links a.is-active { color: var(--red); border-bottom-color: var(--red); }

/* ============================================================
   GLOBAL TYPE TOKENS
   ============================================================ */
.eyebrow {
  font-family: var(--font-mono);
  font-size: 14px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--red);
}
.eyebrow--yellow { color: var(--yellow); }
.eyebrow--black { color: var(--black); }
.eyebrow--chalk { color: var(--chalk); }

h1, h2, h3 {
  font-family: var(--font-head);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: -0.02em;
  line-height: 0.95;
  color: var(--chalk);
}

.h1 { font-size: clamp(48px, 9vw, 112px); }
.h2 { font-size: clamp(36px, 5vw, 64px); }
.h3 { font-size: clamp(24px, 3vw, 32px); }

p { line-height: 1.6; }

/* ============================================================
   BUTTONS
   ============================================================ */
.btn {
  display: inline-block;
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 14px 28px;
  border-radius: 0;
  border: 2px solid transparent;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 80ms linear, color 80ms linear, border-color 80ms linear, transform 80ms linear;
}
.btn--red {
  background: var(--red);
  color: var(--chalk);
  border-color: var(--red);
}
.btn--red:hover {
  background: var(--chalk);
  color: var(--red);
  border-color: var(--chalk);
}
.btn--black {
  background: var(--black);
  color: var(--chalk);
  border-color: var(--black);
}
.btn--black:hover {
  background: var(--chalk);
  color: var(--black);
  border-color: var(--black);
}
.btn--chalk {
  background: var(--chalk);
  color: var(--black);
  border-color: var(--black);
}
.btn--chalk:hover {
  background: var(--red);
  color: var(--chalk);
  border-color: var(--red);
}
.btn--outline-black {
  background: transparent;
  color: var(--black);
  border-color: var(--black);
}
.btn--outline-black:hover {
  background: var(--black);
  color: var(--chalk);
}
.btn--outline-chalk {
  background: var(--black);
  color: var(--chalk);
  border-color: var(--chalk);
}
.btn--outline-chalk:hover {
  background: var(--chalk);
  color: var(--black);
}

.link-blue {
  color: var(--blue);
  font-family: var(--font-body);
  font-size: 15px;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}
.link-blue:hover { text-decoration-thickness: 3px; }

.link-black {
  color: var(--black);
  font-family: var(--font-body);
  font-size: 15px;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}
.link-black:hover { text-decoration-thickness: 3px; }

/* ============================================================
   SECTIONS / SURFACES
   ============================================================ */
.section { padding: 80px 0; position: relative; }
.section--black { background: var(--black); }
.section--slab { background: var(--slab); }
.section--red { background: var(--red); color: var(--black); }
.section--red h1, .section--red h2, .section--red h3 { color: var(--black); }

/* ============================================================
   HOME — HERO (home-section-1)
   ============================================================ */
.hero {
  background: var(--black);
  padding: 48px 0 80px;
  min-height: 92vh;
  display: flex;
  align-items: flex-start;
  overflow: hidden;
  position: relative;
}
.hero-inner { width: 100%; padding: 0 var(--pad-x); max-width: var(--container); margin: 0 auto; }
.hero-logo {
  width: clamp(280px, 38vw, 480px);
  margin-bottom: 24px;
  opacity: 0;
  transform: translate(-40px, -20px);
}
.hero-logo.is-in { opacity: 1; transform: translate(0,0); transition: transform 220ms steps(4,end), opacity 100ms linear; }

.hero-eyebrow { margin-bottom: 32px; opacity: 0; }
.hero-eyebrow.is-in { opacity: 1; transition: opacity 240ms 200ms linear; }

.hero-h1 {
  color: var(--chalk);
  font-size: clamp(52px, 11vw, 120px);
  line-height: 0.92;
  letter-spacing: -0.02em;
  margin-bottom: 28px;
}
.hero-h1-line {
  display: block;
  overflow: visible;
  opacity: 0;
  transform: translateY(28px);
}
.hero-h1-line.is-in { opacity: 1; transform: translateY(0); transition: transform 220ms linear, opacity 100ms linear; }
.hero-h1-line .bleed {
  display: inline-block;
  white-space: nowrap;
}

.hero-sub {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--chalk);
  opacity: 0.8;
  max-width: 600px;
  margin-bottom: 40px;
  min-height: 1.6em;
}
.hero-sub .cursor {
  display: inline-block;
  width: 0.55ch;
  background: var(--chalk);
  color: transparent;
  margin-left: 2px;
  animation: blink 1s steps(2, end) infinite;
  vertical-align: -2px;
}
.hero-sub .cursor.hidden { display: none; }

@keyframes blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

.hero-ctas {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  align-items: center;
  opacity: 0;
  transform: translateX(-30px);
}
.hero-ctas.is-in { opacity: 1; transform: translateX(0); transition: transform 280ms linear, opacity 180ms linear; }

/* ============================================================
   HOME — STATS MARQUEE (home-section-2)
   ============================================================ */
.marquee-section { background: var(--black); padding-top: 48px; padding-bottom: 0; }
.marquee-heading { padding: 0 var(--pad-x); max-width: var(--container); margin: 0 auto 24px; }
.marquee-heading .eyebrow { color: var(--yellow); margin-bottom: 8px; }
.marquee-heading h2 { font-size: clamp(32px, 5vw, 56px); color: var(--chalk); }

.marquee {
  width: 100%;
  overflow: hidden;
  background: var(--black);
  border-top: 2px solid var(--chalk);
  border-bottom: 2px solid var(--chalk);
  padding: 16px 0;
  position: relative;
}
.marquee-track {
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
  animation: marquee 38s linear infinite;
  gap: 64px;
}
.marquee-item {
  display: inline-flex;
  align-items: baseline;
  gap: 20px;
  padding-right: 0;
}
.marquee-num {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: clamp(56px, 10vw, 96px);
  color: var(--red);
  letter-spacing: -0.02em;
  line-height: 1;
}
.marquee-label {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--chalk);
  white-space: normal;
  max-width: 280px;
}
.marquee-divider {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: clamp(56px, 10vw, 96px);
  color: var(--chalk);
  line-height: 1;
}

@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ============================================================
   HOME — FEATURE GRID (home-section-3)
   ============================================================ */
.features { background: var(--slab); padding: 80px 0; }
.features-head { margin-bottom: 40px; }
.features-head .eyebrow { color: var(--yellow); margin-bottom: 8px; }
.features-head h2 { color: var(--chalk); margin-bottom: 16px; font-size: clamp(36px, 5vw, 64px); }
.features-head .sub { font-family: var(--font-body); color: var(--chalk); opacity: 0.7; max-width: 640px; font-size: 16px; }

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.feature-card {
  background: var(--black);
  border: 2px solid var(--chalk);
  padding: 24px;
  display: flex;
  flex-direction: column;
  opacity: 0;
  transform: translateY(24px);
}
.feature-card.is-in { opacity: 1; transform: translateY(0); transition: transform 240ms linear, opacity 120ms linear; }
.feature-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  transition: border-color 80ms linear, transform 120ms linear;
}
.feature-card.is-in:hover { transform: translateY(-4px); }
.feature-card h3 {
  color: var(--chalk);
  font-size: 24px;
  margin-bottom: 12px;
}
.feature-card p {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--chalk);
  opacity: 0.65;
}
.feature-card--yellow { border-color: var(--yellow); }
.feature-card--yellow:hover { border-color: var(--red); }

.features-cta { margin-top: 32px; }

/* ============================================================
   HOME — TESTIMONIALS (home-section-4)
   ============================================================ */
.testimonials { background: var(--black); padding: 64px 0; }
.testimonials-head { margin-bottom: 40px; }
.testimonials-head .eyebrow { color: var(--yellow); margin-bottom: 8px; }
.testimonials-head h2 { font-size: clamp(32px, 4.5vw, 56px); }

.quote-row {
  display: grid;
  grid-template-columns: 38fr 30fr 32fr;
  gap: 32px;
}
.quote-block {
  border-left: 4px solid var(--red);
  padding-left: 16px;
  opacity: 0;
  transform: translateX(-48px);
  transition: border-left-width 1ms linear;
}
.quote-block.is-in { opacity: 1; transform: translateX(0); transition: transform 420ms linear, opacity 280ms linear; }
.quote-block:nth-child(1).is-in { transition-duration: 360ms; }
.quote-block:nth-child(2).is-in { transition-duration: 460ms; }
.quote-block:nth-child(3).is-in { transition-duration: 560ms; }
.quote-block:hover { border-left-width: 8px; padding-left: 12px; }
.quote-mark {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 48px;
  color: var(--red);
  line-height: 1;
  margin-bottom: 8px;
}
.quote-text {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--chalk);
  opacity: 0.85;
  line-height: 1.7;
  margin-bottom: 16px;
}
.quote-attr {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 18px;
  text-transform: uppercase;
  color: var(--chalk);
  margin-bottom: 4px;
  line-height: 1.2;
}
.quote-meta {
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--yellow);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

/* ============================================================
   HOME — CTA CLOSE (home-section-5)
   ============================================================ */
.cta-close {
  background: var(--red);
  padding: 120px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-close-pattern {
  position: absolute;
  inset: -10% 0 -10% 0;
  width: 100%;
  height: 120%;
  opacity: 0.1;
  pointer-events: none;
  animation: drift 30s linear infinite;
}
@keyframes drift {
  0% { transform: translateY(0); }
  100% { transform: translateY(-50%); }
}
.cta-close .eyebrow { color: var(--yellow); margin-bottom: 12px; }
.cta-close h2 {
  color: var(--black);
  font-size: clamp(40px, 7vw, 72px);
  line-height: 1.05;
  margin-bottom: 20px;
  position: relative;
  opacity: 0;
  transform: translateY(-30px);
}
.cta-close.is-in h2 { opacity: 1; transform: translateY(0); transition: transform 280ms linear, opacity 120ms linear; }
.cta-close .sub {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--black);
  opacity: 0.85;
  max-width: 560px;
  margin: 0 auto 32px;
  position: relative;
}
.cta-close-ctas {
  display: inline-flex;
  gap: 24px;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  position: relative;
}

/* ============================================================
   CLASSES PAGE
   ============================================================ */
.page-header-sec {
  background: var(--black);
  padding: 120px 0 80px;
  position: relative;
  overflow: hidden;
}
.ph-grid {
  display: grid;
  grid-template-columns: 65% 35%;
  align-items: center;
  gap: 32px;
}
.ph-text .eyebrow { color: var(--yellow); margin-bottom: 20px; }
.ph-h1 {
  color: var(--chalk);
  font-size: clamp(48px, 10vw, 110px);
  line-height: 0.92;
  letter-spacing: -0.02em;
}
.ph-h1-line {
  display: block;
  opacity: 0;
  transform: translateY(-24px);
}
.ph-h1-line.is-in { opacity: 1; transform: translateY(0); transition: transform 220ms linear, opacity 100ms linear; }
.bleed-word {
  display: inline-block;
  color: var(--red);
  font-size: 1.25em;
  position: relative;
  margin-right: -60px;
  animation-fill-mode: both;
}
.bleed-word.slam { animation: bleedSlam 360ms linear; }
@keyframes bleedSlam {
  0% { transform: translateX(0); }
  35% { transform: translateX(14px); }
  70% { transform: translateX(-2px); }
  100% { transform: translateX(0); }
}

.ph-sub {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--chalk);
  margin-top: 24px;
  max-width: 520px;
  opacity: 0;
}
.ph-sub.is-in { opacity: 1; transition: opacity 400ms 600ms linear; }

.ph-illo { opacity: 0; }
.ph-illo.is-in { opacity: 1; transition: opacity 600ms 400ms linear; }

/* Item grid (classes / instructors / schedule cards) */
.item-grid-sec { background: var(--slab); padding: 80px 0; }
.item-grid-head { margin-bottom: 40px; }
.item-grid-head .eyebrow { color: var(--red); margin-bottom: 12px; }
.item-grid-head h2 { color: var(--chalk); font-size: clamp(32px, 5vw, 56px); }
.item-grid-head .sub { font-family: var(--font-body); color: var(--chalk); opacity: 0.75; margin-top: 16px; }

.cls-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2px;
}
.cls-card {
  background: var(--black);
  border: 1px solid var(--chalk);
  padding: 24px;
  display: flex;
  flex-direction: column;
  min-height: 220px;
  opacity: 0;
  transform: translateY(24px);
}
.cls-card.is-in { opacity: 1; transform: translateY(0); transition: transform 280ms linear, opacity 200ms linear; }
.cls-card h3 {
  color: var(--chalk);
  font-size: 22px;
  margin-bottom: 12px;
  transition: color 80ms linear;
}
.cls-card p {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--chalk);
  opacity: 0.75;
  flex-grow: 1;
  margin-bottom: 16px;
}
.cls-meta {
  padding-top: 12px;
  border-top: 1px solid rgba(242,242,242,0.2);
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--yellow);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.cls-meta span { margin: 0 4px; color: rgba(242,242,242,0.3); }
.cls-card:hover {
  border: 3px solid var(--red);
  padding: 22px;
}
.cls-card:hover h3 { color: var(--red); }

.item-grid-cta { margin-top: 48px; }

/* Comparison */
.compare-sec { background: var(--black); padding: 0; }
.compare-rule {
  height: 3px;
  background: var(--red);
  width: 0;
}
.compare-rule.is-in { width: 100%; transition: width 320ms linear; }
.compare-inner { padding: 80px 0; }
.compare-head { margin-bottom: 40px; }
.compare-head .eyebrow { color: var(--yellow); margin-bottom: 12px; }
.compare-head h2 { color: var(--chalk); font-size: clamp(36px, 5vw, 64px); }

.compare-table {
  width: 100%;
  border-collapse: collapse;
}
.compare-table th, .compare-table td {
  text-align: left;
  padding: 20px;
  border-bottom: 1px solid rgba(242,242,242,0.15);
}
.compare-table th {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--chalk);
  border-bottom: 2px solid var(--chalk);
}
.compare-table th.col-brutalk { color: var(--red); text-align: center; }
.compare-table th.col-app { color: rgba(242,242,242,0.5); text-align: center; }
.compare-table td.col-brutalk, .compare-table td.col-app {
  text-align: center;
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 20px;
}
.compare-table td.col-brutalk { color: var(--red); }
.compare-table td.col-app { color: rgba(242,242,242,0.4); }
.compare-table tbody tr:nth-child(even) { background: var(--slab); }
.compare-table tbody tr {
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 200ms linear, transform 200ms linear, background-color 80ms linear;
}
.compare-table tbody tr.is-in { opacity: 1; transform: translateY(0); }
.compare-table tbody tr:hover { background: rgba(232,0,13,0.12); }
.feat-title {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 15px;
  color: var(--chalk);
}
.feat-desc {
  display: block;
  font-family: var(--font-body);
  font-size: 14px;
  color: rgba(242,242,242,0.65);
  font-weight: normal;
  margin-top: 6px;
}

/* FAQ */
.faq-sec { background: var(--slab); padding: 80px 0; position: relative; }
.faq-grid {
  display: grid;
  grid-template-columns: 25% 70%;
  gap: 5%;
  align-items: start;
}
.faq-icons {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.faq-icon-tile {
  width: 64px;
  height: 64px;
  background: var(--black);
  border: 2px solid var(--chalk);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 28px;
  color: var(--chalk);
  opacity: 0;
  transform: translateX(-24px);
}
.faq-icon-tile.is-in { opacity: 1; transform: translateX(0); transition: transform 240ms linear, opacity 180ms linear; }

.faq-right .eyebrow { color: var(--red); margin-bottom: 12px; }
.faq-right h2 { color: var(--chalk); font-size: clamp(28px, 4.5vw, 48px); margin-bottom: 32px; }
.faq-list { display: flex; flex-direction: column; }
.faq-item {
  border-top: 1px solid rgba(242,242,242,0.2);
  opacity: 0;
  transform: translateY(8px);
}
.faq-item:last-child { border-bottom: 1px solid rgba(242,242,242,0.2); }
.faq-item.is-in { opacity: 1; transform: translateY(0); transition: transform 240ms linear, opacity 180ms linear; }

.faq-q {
  width: 100%;
  background: transparent;
  border: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 20px 0;
  text-align: left;
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 16px;
  color: var(--chalk);
  cursor: pointer;
  transition: color 80ms linear;
}
.faq-q:hover { color: var(--blue); }
.faq-toggle {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 20px;
  color: var(--red);
  display: inline-block;
  transition: transform 120ms linear;
}
.faq-item.is-open .faq-toggle { transform: rotate(45deg); }
.faq-a {
  max-height: 0;
  overflow: hidden;
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--chalk);
  opacity: 0.8;
  line-height: 1.6;
  transition: max-height 140ms linear;
}
.faq-item.is-open .faq-a { max-height: 400px; padding-bottom: 16px; }

.faq-cta { margin-top: 40px; }

/* CTA close (classes / generic) */
.cta-red-sec {
  background: var(--red);
  color: var(--black);
  padding: 80px 0;
  position: relative;
}
.cta-red-sec .eyebrow { color: var(--black); margin-bottom: 16px; }
.cta-red-sec h2 {
  color: var(--black);
  font-size: clamp(40px, 7vw, 80px);
  line-height: 1;
}
.cta-red-sec .sub {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--black);
  max-width: 480px;
  margin: 20px 0 32px;
}
.cta-red-ctas { display: flex; gap: 16px; flex-wrap: wrap; }

.btn-pulse {
  position: relative;
  animation: pulseBorder 2s ease-in-out infinite;
}
@keyframes pulseBorder {
  0%, 100% { box-shadow: inset 0 0 0 2px rgba(242,242,242,0); }
  50%      { box-shadow: inset 0 0 0 2px rgba(242,242,242,1); }
}

/* ============================================================
   SCHEDULE PAGE
   ============================================================ */
.sched-header { background: var(--black); padding: 80px 0 40px; }
.sched-header-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
}
.cal-icon { width: 28px; height: 28px; flex-shrink: 0; }
.sched-h1 {
  color: var(--chalk);
  font-size: clamp(40px, 8vw, 96px);
  line-height: 0.95;
  letter-spacing: -0.02em;
  opacity: 0;
  transform: translateX(-40px);
}
.sched-h1.is-in { opacity: 1; transform: translateX(0); transition: transform 320ms linear, opacity 200ms linear; }
.sched-sub {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--chalk);
  opacity: 0.75;
  max-width: 640px;
  margin-top: 24px;
}

.sched-grid-sec {
  background: var(--black);
  padding: 60px 0 80px;
  position: relative;
  overflow: hidden;
}
.sched-bg-word {
  position: absolute;
  right: -10%;
  top: 50%;
  transform: translate(120%, -45%);
  font-family: var(--font-head);
  font-weight: 900;
  font-size: clamp(120px, 22vw, 240px);
  color: var(--yellow);
  opacity: 0.18;
  letter-spacing: -0.04em;
  text-transform: uppercase;
  pointer-events: none;
  z-index: 0;
  white-space: nowrap;
}
.sched-bg-word.is-in { transform: translate(0, -45%); transition: transform 900ms linear; }
.sched-grid-inner { position: relative; z-index: 2; }
.sched-grid-head { margin-bottom: 32px; }
.sched-grid-head .eyebrow { color: var(--yellow); margin-bottom: 12px; }
.sched-grid-head h2 { color: var(--chalk); font-size: clamp(32px, 5vw, 64px); }

.sched-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.sched-card {
  background: var(--slab);
  border: 2px solid var(--chalk);
  padding: 20px;
  position: relative;
  display: flex;
  flex-direction: column;
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 200ms linear, transform 200ms linear, border-color 80ms linear, box-shadow 80ms linear;
}
.sched-card.is-in { opacity: 1; transform: translateY(0); }
.sched-card-tag {
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--yellow);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 8px;
}
.sched-card h3 {
  color: var(--chalk);
  font-size: 22px;
  letter-spacing: -0.01em;
  margin-bottom: 12px;
}
.sched-card-desc {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--chalk);
  opacity: 0.7;
  line-height: 1.5;
  margin-bottom: 16px;
  flex-grow: 1;
}
.sched-card-foot {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.sched-badge {
  font-family: var(--font-mono);
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  padding: 4px 8px;
  background: var(--black);
}
.sched-badge--plain { color: var(--chalk); background: transparent; padding-left: 0; }
.sched-badge--warn { color: var(--yellow); animation: badgePulse 2s ease-in-out infinite; }
.sched-badge--full { color: var(--red); animation: badgePulse 2s ease-in-out infinite; }
@keyframes badgePulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.7; }
}
.sched-btn {
  background: var(--red);
  color: var(--chalk);
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 13px;
  text-transform: uppercase;
  padding: 6px 10px;
  border: 0;
  cursor: pointer;
  text-decoration: none;
  transition: background-color 80ms linear, color 80ms linear;
}
.sched-btn:hover { background: var(--chalk); color: var(--black); }
.sched-btn--wait { background: var(--yellow); color: var(--black); }
.sched-btn--wait:hover { background: var(--chalk); color: var(--black); }

.sched-card:hover:not(.sched-card--full) {
  border: 3px solid var(--red);
  padding: 19px;
  transform: translateY(-4px);
  box-shadow: 4px 4px 0 var(--red);
}
.sched-card--full:hover { border: 3px solid var(--yellow); padding: 19px; }

.sched-after-link { margin-top: 32px; }

/* Stats strip */
.stats-strip-sec { background: var(--slab); padding: 40px 0; }
.stats-head { margin-bottom: 24px; }
.stats-head .eyebrow { color: var(--red); margin-bottom: 8px; }
.stats-head h2 { color: var(--chalk); font-size: clamp(28px, 4vw, 48px); }

.stats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
}
.stat-unit { display: flex; flex-direction: column; }
.stat-unit .micro {
  font-family: var(--font-mono);
  font-size: 13px;
  color: var(--yellow);
  text-transform: uppercase;
  letter-spacing: 0.08em;
  margin-bottom: 4px;
}
.stat-num {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: clamp(48px, 8vw, 80px);
  color: var(--red);
  letter-spacing: -0.02em;
  line-height: 1;
}
.stat-title {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 24px;
  text-transform: uppercase;
  color: var(--chalk);
  margin-top: 4px;
  letter-spacing: -0.01em;
}
.stat-desc {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--chalk);
  opacity: 0.7;
  line-height: 1.5;
  max-width: 220px;
  margin-top: 8px;
}

/* Story block */
.story-sec { background: var(--black); padding: 80px 0; }
.story-grid {
  display: grid;
  grid-template-columns: 55% 45%;
  gap: 48px;
  align-items: center;
}
.story-text {
  opacity: 0;
  transform: translateY(20px);
}
.story-text.is-in { opacity: 1; transform: translateY(0); transition: transform 500ms linear, opacity 400ms linear; }
.story-text .eyebrow { color: var(--yellow); margin-bottom: 12px; }
.story-text h2 {
  color: var(--chalk);
  font-size: clamp(32px, 5vw, 56px);
  line-height: 1;
  margin-bottom: 24px;
}
.story-text p {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--chalk);
  opacity: 0.85;
  max-width: 520px;
  line-height: 1.7;
  margin-bottom: 12px;
}
.story-chart {
  opacity: 0;
  transform: translateX(40px);
}
.story-chart.is-in { opacity: 1; transform: translateX(0); transition: transform 500ms linear, opacity 400ms linear; }

/* ============================================================
   INSTRUCTORS PAGE
   ============================================================ */
.instr-header { background: var(--black); padding: 80px 0 64px; position: relative; overflow: hidden; }
.instr-header-grid {
  display: grid;
  grid-template-columns: 7fr 5fr;
  gap: 32px;
  align-items: center;
}
.instr-header .eyebrow {
  color: var(--red);
  margin-bottom: 16px;
  display: inline-flex;
  align-items: baseline;
  gap: 4px;
}
.cursor-blink {
  display: inline-block;
  background: var(--red);
  width: 0.5ch;
  height: 1em;
  vertical-align: -2px;
  animation: blink2 1s steps(2,end) infinite;
}
@keyframes blink2 {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}
.instr-rule {
  height: 2px;
  background: var(--red);
  width: 100%;
  margin-bottom: 32px;
}
.instr-h1 {
  color: var(--chalk);
  font-size: clamp(40px, 8vw, 96px);
  line-height: 0.95;
  letter-spacing: -0.02em;
  opacity: 0;
  transform: translateX(-40px);
}
.instr-h1.is-in { opacity: 1; transform: translateX(0); transition: transform 320ms linear, opacity 200ms linear; }
.instr-sub {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--chalk);
  max-width: 520px;
  margin-top: 24px;
  opacity: 0;
}
.instr-sub.is-in { opacity: 1; transition: opacity 400ms linear; }

.instr-200-wrap {
  position: relative;
  height: 360px;
  display: flex;
  align-items: center;
  justify-content: center;
}
.instr-silhouettes {
  width: 100%;
  height: 100%;
  opacity: 0.6;
}
.instr-200 {
  position: absolute;
  right: -8%;
  top: 50%;
  transform: translate(40px, -50%);
  font-family: var(--font-head);
  font-weight: 900;
  font-size: clamp(72px, 11vw, 120px);
  color: var(--yellow);
  letter-spacing: -0.02em;
  line-height: 1;
  z-index: 2;
  opacity: 0;
}
.instr-200.is-in { opacity: 1; transform: translate(0, -50%); transition: transform 320ms cubic-bezier(0.34, 1.56, 0.64, 1), opacity 120ms linear; }

/* Instructor roster */
.instr-grid-sec { background: var(--black); padding: 64px 0; }
.instr-grid-head { margin-bottom: 32px; }
.instr-grid-head .eyebrow { color: var(--red); margin-bottom: 12px; }
.instr-grid-head h2 { color: var(--chalk); font-size: clamp(36px, 5vw, 64px); }

.instr-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}
.instr-card {
  background: var(--slab);
  border: 1px solid var(--chalk);
  padding: 24px;
  display: flex;
  flex-direction: column;
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 220ms linear, transform 220ms linear;
}
.instr-card.is-in { opacity: 1; transform: translateY(0); }
.instr-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  margin-bottom: 24px;
}
.instr-badge {
  font-family: var(--font-mono);
  font-size: 13px;
  letter-spacing: 0.06em;
  padding: 2px 4px;
  background: var(--black);
}
.instr-badge--lang { color: var(--yellow); border: 1px solid var(--yellow); }
.instr-badge--cred { color: var(--chalk); border: 1px solid var(--chalk); }
.instr-badge--yrs { color: var(--red); background: transparent; border: 0; }

.instr-name {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 20px;
  color: var(--blue);
  text-transform: uppercase;
  text-decoration: none;
  line-height: 1.1;
  transition: color 80ms linear;
}
.instr-card p {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--chalk);
  opacity: 0.85;
  margin-top: 12px;
  line-height: 1.6;
  flex-grow: 1;
}
.instr-card hr {
  border: 0;
  border-top: 1px solid var(--chalk);
  margin-top: 16px;
}
.instr-card:hover {
  border: 4px solid var(--red);
  padding: 21px;
  transform: translateY(-4px);
}
.instr-card.is-in:hover { transform: translateY(-4px); }
.instr-card:hover .instr-name { color: var(--chalk); }

/* Instructors story block (red) */
.instr-story-sec {
  background: var(--red);
  color: var(--chalk);
  padding: 80px 0;
  opacity: 0;
  transform: translateY(40px);
}
.instr-story-sec.is-in { opacity: 1; transform: translateY(0); transition: transform 460ms linear, opacity 280ms linear; }
.instr-story-inner { max-width: 800px; }
.instr-story-sec .eyebrow { color: var(--chalk); margin-bottom: 12px; }
.instr-story-rule { height: 2px; background: var(--chalk); width: 100%; margin-bottom: 24px; }
.instr-story-sec h2 {
  color: var(--chalk);
  font-size: clamp(36px, 6vw, 72px);
  line-height: 1;
  margin-bottom: 24px;
}
.instr-story-sec p {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--chalk);
  line-height: 1.6;
}
.instr-accent {
  font-family: var(--font-head);
  font-weight: 900;
  color: var(--yellow);
  font-size: 1em;
}

/* Timeline */
.timeline-sec { background: var(--black); padding: 64px 0; }
.timeline-head { margin-bottom: 32px; }
.timeline-head .eyebrow { color: var(--red); margin-bottom: 12px; }
.timeline-head h2 { color: var(--chalk); font-size: clamp(28px, 4.5vw, 56px); }

.timeline {
  position: relative;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px;
  padding-top: 32px;
}
.timeline-line {
  position: absolute;
  left: 0;
  right: 0;
  top: 64px;
  height: 2px;
  background: var(--chalk);
  transform-origin: left center;
  transform: scaleX(0);
}
.timeline-line.is-in { transform: scaleX(1); transition: transform 400ms linear; }
.stage {
  text-align: left;
  position: relative;
  z-index: 2;
  opacity: 0;
}
.stage.is-in { opacity: 1; transition: opacity 200ms linear; }
.stage-circle {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  border: 3px solid var(--chalk);
  background: var(--black);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-mono);
  font-size: 32px;
  color: var(--yellow);
  margin-bottom: 16px;
  transition: background-color 80ms linear, color 80ms linear;
  cursor: default;
}
.stage:hover .stage-circle { background: var(--red); color: var(--chalk); border-color: var(--red); }
.stage h3 {
  color: var(--chalk);
  font-size: 22px;
  margin-bottom: 12px;
}
.stage p {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--chalk);
  opacity: 0.85;
}

/* Instructors CTA close */
.instr-cta-sec { background: var(--black); padding: 96px 0; }
.instr-cta-rule { height: 2px; background: var(--red); width: 100%; margin: 16px 0 24px; }
.instr-cta-sec .eyebrow { color: var(--red); margin-bottom: 12px; }
.instr-cta-sec h2 {
  color: var(--chalk);
  font-size: clamp(40px, 7vw, 80px);
  line-height: 1;
  opacity: 0;
  transform: translateX(-40px);
}
.instr-cta-sec h2 .now-red { color: var(--red); }
.instr-cta-sec h2.is-in { opacity: 1; transform: translateX(0); transition: transform 320ms linear, opacity 200ms linear; }
.instr-cta-sec .sub {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--chalk);
  opacity: 0.85;
  max-width: 560px;
  margin: 24px 0 40px;
}
.instr-cta-grp { display: flex; gap: 32px; align-items: center; flex-wrap: wrap; }

/* ============================================================
   PRICING PAGE
   ============================================================ */
.pricing-header { background: var(--black); padding: 80px 0 64px; }
.pricing-header .eyebrow { color: var(--yellow); margin-bottom: 12px; }
.pricing-h1 {
  color: var(--chalk);
  font-size: clamp(40px, 8vw, 96px);
  line-height: 0.95;
  letter-spacing: -0.02em;
  min-height: 1.9em;
}
.pricing-h1 .typewriter-cursor {
  display: inline-block;
  width: 0.5ch;
  background: var(--chalk);
  color: transparent;
  margin-left: 4px;
  animation: blink 1s steps(2,end) infinite;
  vertical-align: -8px;
}
.pricing-h1 .typewriter-cursor.hidden { display: none; }
.pricing-sub {
  font-family: var(--font-body);
  font-size: 18px;
  color: var(--chalk);
  opacity: 0.8;
  max-width: 640px;
  margin-top: 24px;
  opacity: 0;
  transform: translateY(16px);
}
.pricing-sub.is-in { opacity: 0.8; transform: translateY(0); transition: opacity 320ms linear, transform 320ms linear; }
.pricing-rule {
  height: 2px;
  background: var(--red);
  width: 0;
  margin-top: 32px;
}
.pricing-rule.is-in { width: 100%; transition: width 400ms linear; }

.pricing-cards-sec { background: var(--black); padding: 80px 0 48px; }
.pricing-cards-sec .eyebrow { color: var(--yellow); margin-bottom: 12px; }
.pricing-cards-sec h2 {
  color: var(--chalk);
  font-size: clamp(32px, 5vw, 56px);
  margin-bottom: 64px;
}

.plan-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 48px;
}
.plan {
  background: var(--slab);
  border: 1px solid var(--slab-edge);
  padding: 32px;
  position: relative;
  display: flex;
  flex-direction: column;
  opacity: 0;
  transform: translateY(32px);
  transition: opacity 280ms linear, transform 280ms linear, border-color 120ms linear, box-shadow 120ms linear;
}
.plan.is-in { opacity: 1; transform: translateY(0); }
.plan:hover {
  border: 2px solid var(--red);
  padding: 31px;
  box-shadow: 4px 4px 0 var(--red);
}
.plan-label {
  font-family: var(--font-mono);
  font-size: 14px;
  letter-spacing: 0.08em;
  color: var(--yellow);
  text-transform: uppercase;
  margin-bottom: 4px;
}
.plan-price {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 56px;
  color: var(--chalk);
  letter-spacing: -0.02em;
  line-height: 1;
  margin-bottom: 16px;
}
.plan p {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--chalk);
  opacity: 0.85;
  margin-bottom: 20px;
  flex-grow: 1;
}
.plan-feats {
  list-style: none;
  margin-bottom: 24px;
  padding: 0;
}
.plan-feats li {
  font-family: var(--font-mono);
  font-size: 14px;
  letter-spacing: 0.05em;
  color: var(--chalk);
  text-transform: uppercase;
  padding: 4px 0;
  border-bottom: 1px dashed rgba(242,242,242,0.1);
}
.plan .btn {
  width: 100%;
  text-align: center;
}

.plan--featured {
  border-left: 8px solid var(--red);
  padding-left: 32px;
  position: relative;
}
.plan--featured:hover { border: 2px solid var(--red); border-left: 8px solid var(--red); padding-left: 31px; }
.plan--featured .plan-badge {
  position: absolute;
  top: 16px;
  right: 16px;
  background: var(--red);
  color: var(--yellow);
  font-family: var(--font-mono);
  font-size: 13px;
  letter-spacing: 0.08em;
  padding: 4px 8px;
  text-transform: uppercase;
  animation: badgePulse 2s ease-in-out infinite;
}
.plan--featured .plan-price {
  font-size: 80px;
  color: var(--red);
  margin-top: -42px;
  margin-bottom: 8px;
  position: relative;
}
.plan--featured .plan-price.slam { animation: priceSlam 360ms linear; }
@keyframes priceSlam {
  0% { transform: translateY(-12px); }
  60% { transform: translateY(8px); }
  100% { transform: translateY(0); }
}

.compare-chart {
  background: var(--slab);
  padding: 32px;
  margin-bottom: 32px;
}
.cc-grid {
  display: grid;
  grid-template-columns: 2fr 1fr 1fr 1fr;
  gap: 12px;
  align-items: center;
}
.cc-grid > div { padding: 8px 4px; }
.cc-grid .cc-head {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 16px;
  text-transform: uppercase;
  color: var(--chalk);
  border-bottom: 2px solid var(--chalk);
}
.cc-grid .cc-head--committed { color: var(--red); }
.cc-grid .cc-row-label {
  font-family: var(--font-mono);
  font-size: 14px;
  letter-spacing: 0.08em;
  color: var(--yellow);
  text-transform: uppercase;
}
.cc-bar {
  height: 14px;
  background: var(--chalk);
  display: block;
}
.cc-bar--red { background: var(--red); }
.cc-row-divider { grid-column: 1 / -1; height: 1px; background: rgba(242,242,242,0.1); }

.pricing-after-cta { display: flex; gap: 24px; align-items: center; flex-wrap: wrap; margin-top: 24px; }

/* Pricing stats */
.pricing-stats-sec { background: var(--black); padding: 80px 0; position: relative; }
.pricing-stats-rule {
  position: absolute;
  left: var(--pad-x);
  top: 80px;
  bottom: 80px;
  width: 2px;
  background: var(--red);
}
.pricing-stats-sec .eyebrow { color: var(--yellow); margin-bottom: 12px; }
.pricing-stats-sec h2 { color: var(--chalk); font-size: clamp(32px, 5vw, 56px); margin-bottom: 48px; }

.pstats-row {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
  position: relative;
}
.pstat {
  padding: 0 16px 0 24px;
  border-left: 1px solid var(--slab-edge);
}
.pstat:first-child { border-left: 0; padding-left: 0; }
.pstat .num {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: clamp(40px, 6vw, 80px);
  color: var(--chalk);
  letter-spacing: -0.02em;
  line-height: 1;
  margin-bottom: 12px;
}
.pstat .num .unit {
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--yellow);
  letter-spacing: 0.06em;
  margin-left: 2px;
}
.pstat p {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--chalk);
  opacity: 0.7;
  max-width: 200px;
}

/* Pricing FAQ */
.pricing-faq-sec { background: var(--black); padding: 80px 0; position: relative; }
.pricing-faq-shield {
  position: absolute;
  top: 80px;
  right: var(--pad-x);
  width: 64px;
  height: 64px;
  z-index: 2;
}
.pricing-faq-sec .eyebrow { color: var(--yellow); margin-bottom: 12px; }
.pricing-faq-sec h2 { color: var(--chalk); font-size: clamp(28px, 4.5vw, 56px); margin-bottom: 40px; max-width: 800px; }

.pfaq-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  max-width: 800px;
}
.pfaq-item {
  background: var(--slab);
  border-left: 2px solid var(--blue);
  padding: 24px 32px;
  opacity: 0;
  transform: translateX(-24px);
  transition: opacity 220ms linear, transform 220ms linear, border-left-color 120ms linear;
}
.pfaq-item.is-in { opacity: 1; transform: translateX(0); }
.pfaq-item:hover { border-left-color: var(--red); }
.pfaq-q {
  display: flex;
  gap: 12px;
  align-items: baseline;
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 20px;
  text-transform: uppercase;
  color: var(--chalk);
  transition: color 120ms linear;
  margin-bottom: 12px;
}
.pfaq-item:hover .pfaq-q { color: var(--yellow); }
.pfaq-prefix {
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--yellow);
}
.pfaq-a {
  display: flex;
  gap: 12px;
  align-items: baseline;
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--blue);
  line-height: 1.6;
}

/* Pricing CTA close */
.pricing-cta-sec { background: var(--red); color: var(--black); padding: 96px 0; }
.pricing-cta-sec .eyebrow { color: var(--black); margin-bottom: 12px; }
.pricing-cta-sec h2 {
  color: var(--black);
  font-size: clamp(40px, 8vw, 96px);
  line-height: 1;
  letter-spacing: -0.02em;
  opacity: 0;
}
.pricing-cta-sec h2.is-in { opacity: 1; transition: opacity 80ms linear; }
.pricing-cta-sec .sub {
  font-family: var(--font-body);
  font-size: 18px;
  color: var(--black);
  opacity: 0.9;
  max-width: 560px;
  margin: 24px 0 40px;
}
.pricing-cta-grp { display: flex; gap: 24px; align-items: center; flex-wrap: wrap; }

/* ============================================================
   FOOTER
   ============================================================ */
.footer {
  background: var(--black);
  border-top: 2px solid var(--chalk);
  padding: 48px 0 32px;
}
.footer-inner {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 24px;
}
.footer-brand {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 20px;
  color: var(--chalk);
  text-transform: uppercase;
}
.footer-links {
  display: flex;
  gap: 24px;
  list-style: none;
}
.footer-links a {
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--chalk);
  text-decoration: none;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}
.footer-links a:hover { color: var(--red); }
.footer-meta {
  font-family: var(--font-body);
  font-size: 13px;
  color: var(--chalk);
  opacity: 0.55;
}

/* ============================================================
   RESPONSIVE
   ============================================================ */
@media (max-width: 1024px) {
  .feature-grid { grid-template-columns: repeat(2, 1fr); }
  .cls-grid { grid-template-columns: repeat(2, 1fr); }
  .instr-grid { grid-template-columns: repeat(2, 1fr); }
  .stats-row { grid-template-columns: repeat(2, 1fr); }
  .pstats-row { grid-template-columns: repeat(2, 1fr); }
  .timeline { grid-template-columns: repeat(2, 1fr); }
  .timeline-line { display: none; }
  .ph-grid { grid-template-columns: 1fr; }
  .story-grid { grid-template-columns: 1fr; gap: 40px; }
  .instr-header-grid { grid-template-columns: 1fr; }
  .quote-row { grid-template-columns: 1fr 1fr 1fr; gap: 24px; }
  .faq-grid { grid-template-columns: 1fr; gap: 32px; }
  .faq-icons { flex-direction: row; flex-wrap: wrap; }
}

@media (max-width: 768px) {
  :root { --pad-x: 24px; }
  .nav-links { gap: 12px; }
  .nav-links a { font-size: 14px; }
  .hero { min-height: auto; padding: 32px 0 64px; }
  .feature-grid { grid-template-columns: 1fr; }
  .cls-grid { grid-template-columns: 1fr; }
  .sched-grid { grid-template-columns: 1fr; }
  .instr-grid { grid-template-columns: 1fr; }
  .quote-row { grid-template-columns: 1fr; gap: 32px; }
  .plan-grid { grid-template-columns: 1fr; }
  .pstats-row { grid-template-columns: 1fr 1fr; }
  .pricing-stats-rule { display: none; }
  .pricing-faq-shield { width: 48px; height: 48px; top: 60px; }
  .sched-bg-word { display: none; }
  .bleed-word { margin-right: 0; }
  .cta-red-ctas { flex-direction: column; align-items: flex-start; }
  .cta-red-ctas .btn { width: 100%; text-align: center; }
  .cta-close-ctas { flex-direction: column; align-items: stretch; }
  .marquee-num { font-size: 64px; }
  .marquee-divider { font-size: 64px; }
  .plan--featured .plan-price { font-size: 64px; }
  .timeline { grid-template-columns: 1fr; gap: 24px; }
  .compare-table th, .compare-table td { padding: 12px 8px; font-size: 13px; }
  .compare-table td.col-brutalk, .compare-table td.col-app { font-size: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.001ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.001ms !important;
  }
}

