/* ============================================================
   BRUTALK — Brutalist Raw Language Learning Platform
   Shared stylesheet
   ============================================================ */

@import url('https://fonts.googleapis.com/css2?family=VT323&display=swap');

:root {
  --black: #0A0A0A;
  --chalk: #F2F2F2;
  --red: #E8000D;
  --blue: #0000EE;
  --slab: #1E1E1E;
  --yellow: #FFD600;
  --slab-edge: #2E2E2E;

  --font-head: 'Arial Black', 'Arial Bold', Arial, sans-serif;
  --font-body: 'Courier New', Courier, monospace;
  --font-mono: 'VT323', 'Courier New', monospace;

  --container: 1280px;
  --pad-x: 48px;
}

* { box-sizing: border-box; margin: 0; padding: 0; }

html { scroll-behavior: smooth; }

body {
  background: var(--black);
  color: var(--chalk);
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

a { color: var(--blue); text-decoration: underline; }
a:hover { text-decoration-thickness: 3px; }

img, svg { display: block; max-width: 100%; }

.container {
  max-width: var(--container);
  margin: 0 auto;
  padding: 0 var(--pad-x);
}

/* ============================================================
   NAVIGATION
   ============================================================ */
.nav {
  position: sticky;
  top: 0;
  z-index: 100;
  background: var(--black);
  border-bottom: 2px solid var(--chalk);
}
.nav-inner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 64px;
  padding: 0 var(--pad-x);
  max-width: 100%;
}
.nav-brand {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 22px;
  letter-spacing: -0.02em;
  color: var(--chalk);
  text-decoration: none;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.nav-brand .slash {
  display: inline-block;
  color: var(--red);
  transform: skewX(-18deg);
  font-weight: 900;
}
.nav-links {
  display: flex;
  gap: 24px;
  list-style: none;
}
.nav-links a {
  font-family: var(--font-mono);
  font-size: 16px;
  color: var(--chalk);
  text-decoration: none;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  padding: 6px 4px;
  border-bottom: 2px solid transparent;
  transition: color 80ms linear, border-color 80ms linear;
}
.nav-links a:hover { color: var(--red); border-bottom-color: var(--red); }
.nav-links a.is-active { color: var(--red); border-bottom-color: var(--red); }

/* ============================================================
   GLOBAL TYPE TOKENS
   ============================================================ */
.eyebrow {
  font-family: var(--font-mono);
  font-size: 14px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--red);
}
.eyebrow--yellow { color: var(--yellow); }
.eyebrow--black { color: var(--black); }
.eyebrow--chalk { color: var(--chalk); }

h1, h2, h3 {
  font-family: var(--font-head);
  font-weight: 900;
  text-transform: uppercase;
  letter-spacing: -0.02em;
  line-height: 0.95;
  color: var(--chalk);
}

.h1 { font-size: clamp(48px, 9vw, 112px); }
.h2 { font-size: clamp(36px, 5vw, 64px); }
.h3 { font-size: clamp(24px, 3vw, 32px); }

p { line-height: 1.6; }

/* ============================================================
   BUTTONS
   ============================================================ */
.btn {
  display: inline-block;
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  padding: 14px 28px;
  border-radius: 0;
  border: 2px solid transparent;
  text-decoration: none;
  cursor: pointer;
  transition: background-color 80ms linear, color 80ms linear, border-color 80ms linear, transform 80ms linear;
}
.btn--red {
  background: var(--red);
  color: var(--chalk);
  border-color: var(--red);
}
.btn--red:hover {
  background: var(--chalk);
  color: var(--red);
  border-color: var(--chalk);
}
.btn--black {
  background: var(--black);
  color: var(--chalk);
  border-color: var(--black);
}
.btn--black:hover {
  background: var(--chalk);
  color: var(--black);
  border-color: var(--black);
}
.btn--chalk {
  background: var(--chalk);
  color: var(--black);
  border-color: var(--black);
}
.btn--chalk:hover {
  background: var(--red);
  color: var(--chalk);
  border-color: var(--red);
}
.btn--outline-black {
  background: transparent;
  color: var(--black);
  border-color: var(--black);
}
.btn--outline-black:hover {
  background: var(--black);
  color: var(--chalk);
}
.btn--outline-chalk {
  background: var(--black);
  color: var(--chalk);
  border-color: var(--chalk);
}
.btn--outline-chalk:hover {
  background: var(--chalk);
  color: var(--black);
}

.link-blue {
  color: var(--blue);
  font-family: var(--font-body);
  font-size: 15px;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}
.link-blue:hover { text-decoration-thickness: 3px; }

.link-black {
  color: var(--black);
  font-family: var(--font-body);
  font-size: 15px;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}
.link-black:hover { text-decoration-thickness: 3px; }

/* ============================================================
   SECTIONS / SURFACES
   ============================================================ */
.section { padding: 80px 0; position: relative; }
.section--black { background: var(--black); }
.section--slab { background: var(--slab); }
.section--red { background: var(--red); color: var(--black); }
.section--red h1, .section--red h2, .section--red h3 { color: var(--black); }

/* ============================================================
   HOME — HERO (home-section-1)
   ============================================================ */
.hero {
  background: var(--black);
  padding: 48px 0 80px;
  min-height: 92vh;
  display: flex;
  align-items: flex-start;
  overflow: hidden;
  position: relative;
}
.hero-inner { width: 100%; padding: 0 var(--pad-x); max-width: var(--container); margin: 0 auto; }
.hero-logo {
  width: clamp(280px, 38vw, 480px);
  margin-bottom: 24px;
  opacity: 0;
  transform: translate(-40px, -20px);
}
.hero-logo.is-in { opacity: 1; transform: translate(0,0); transition: transform 220ms steps(4,end), opacity 100ms linear; }

.hero-eyebrow { margin-bottom: 32px; opacity: 0; }
.hero-eyebrow.is-in { opacity: 1; transition: opacity 240ms 200ms linear; }

.hero-h1 {
  color: var(--chalk);
  font-size: clamp(52px, 11vw, 120px);
  line-height: 0.92;
  letter-spacing: -0.02em;
  margin-bottom: 28px;
}
.hero-h1-line {
  display: block;
  overflow: visible;
  opacity: 0;
  transform: translateY(28px);
}
.hero-h1-line.is-in { opacity: 1; transform: translateY(0); transition: transform 220ms linear, opacity 100ms linear; }
.hero-h1-line .bleed {
  display: inline-block;
  white-space: nowrap;
}

.hero-sub {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--chalk);
  opacity: 0.8;
  max-width: 600px;
  margin-bottom: 40px;
  min-height: 1.6em;
}
.hero-sub .cursor {
  display: inline-block;
  width: 0.55ch;
  background: var(--chalk);
  color: transparent;
  margin-left: 2px;
  animation: blink 1s steps(2, end) infinite;
  vertical-align: -2px;
}
.hero-sub .cursor.hidden { display: none; }

@keyframes blink {
  0%, 49% { opacity: 1; }
  50%, 100% { opacity: 0; }
}

.hero-ctas {
  display: flex;
  gap: 24px;
  flex-wrap: wrap;
  align-items: center;
  opacity: 0;
  transform: translateX(-30px);
}
.hero-ctas.is-in { opacity: 1; transform: translateX(0); transition: transform 280ms linear, opacity 180ms linear; }

/* ============================================================
   HOME — STATS MARQUEE (home-section-2)
   ============================================================ */
.marquee-section { background: var(--black); padding-top: 48px; padding-bottom: 0; }
.marquee-heading { padding: 0 var(--pad-x); max-width: var(--container); margin: 0 auto 24px; }
.marquee-heading .eyebrow { color: var(--yellow); margin-bottom: 8px; }
.marquee-heading h2 { font-size: clamp(32px, 5vw, 56px); color: var(--chalk); }

.marquee {
  width: 100%;
  overflow: hidden;
  background: var(--black);
  border-top: 2px solid var(--chalk);
  border-bottom: 2px solid var(--chalk);
  padding: 16px 0;
  position: relative;
}
.marquee-track {
  display: inline-flex;
  align-items: center;
  white-space: nowrap;
  animation: marquee 38s linear infinite;
  gap: 64px;
}
.marquee-item {
  display: inline-flex;
  align-items: baseline;
  gap: 20px;
  padding-right: 0;
}
.marquee-num {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: clamp(56px, 10vw, 96px);
  color: var(--red);
  letter-spacing: -0.02em;
  line-height: 1;
}
.marquee-label {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--chalk);
  white-space: normal;
  max-width: 280px;
}
.marquee-divider {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: clamp(56px, 10vw, 96px);
  color: var(--chalk);
  line-height: 1;
}

@keyframes marquee {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

/* ============================================================
   HOME — FEATURE GRID (home-section-3)
   ============================================================ */
.features { background: var(--slab); padding: 80px 0; }
.features-head { margin-bottom: 40px; }
.features-head .eyebrow { color: var(--yellow); margin-bottom: 8px; }
.features-head h2 { color: var(--chalk); margin-bottom: 16px; font-size: clamp(36px, 5vw, 64px); }
.features-head .sub { font-family: var(--font-body); color: var(--chalk); opacity: 0.7; max-width: 640px; font-size: 16px; }

.feature-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.feature-card {
  background: var(--black);
  border: 2px solid var(--chalk);
  padding: 24px;
  display: flex;
  flex-direction: column;
  opacity: 0;
  transform: translateY(24px);
}
.feature-card.is-in { opacity: 1; transform: translateY(0); transition: transform 240ms linear, opacity 120ms linear; }
.feature-card:hover {
  border-color: var(--red);
  transform: translateY(-4px);
  transition: border-color 80ms linear, transform 120ms linear;
}
.feature-card.is-in:hover { transform: translateY(-4px); }
.feature-card h3 {
  color: var(--chalk);
  font-size: 24px;
  margin-bottom: 12px;
}
.feature-card p {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--chalk);
  opacity: 0.65;
}
.feature-card--yellow { border-color: var(--yellow); }
.feature-card--yellow:hover { border-color: var(--red); }

.features-cta { margin-top: 32px; }

/* ============================================================
   HOME — TESTIMONIALS (home-section-4)
   ============================================================ */
.testimonials { background: var(--black); padding: 64px 0; }
.testimonials-head { margin-bottom: 40px; }
.testimonials-head .eyebrow { color: var(--yellow); margin-bottom: 8px; }
.testimonials-head h2 { font-size: clamp(32px, 4.5vw, 56px); }

.quote-row {
  display: grid;
  grid-template-columns: 38fr 30fr 32fr;
  gap: 32px;
}
.quote-block {
  border-left: 4px solid var(--red);
  padding-left: 16px;
  opacity: 0;
  transform: translateX(-48px);
  transition: border-left-width 1ms linear;
}
.quote-block.is-in { opacity: 1; transform: translateX(0); transition: transform 420ms linear, opacity 280ms linear; }
.quote-block:nth-child(1).is-in { transition-duration: 360ms; }
.quote-block:nth-child(2).is-in { transition-duration: 460ms; }
.quote-block:nth-child(3).is-in { transition-duration: 560ms; }
.quote-block:hover { border-left-width: 8px; padding-left: 12px; }
.quote-mark {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 48px;
  color: var(--red);
  line-height: 1;
  margin-bottom: 8px;
}
.quote-text {
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--chalk);
  opacity: 0.85;
  line-height: 1.7;
  margin-bottom: 16px;
}
.quote-attr {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 18px;
  text-transform: uppercase;
  color: var(--chalk);
  margin-bottom: 4px;
  line-height: 1.2;
}
.quote-meta {
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--yellow);
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

/* ============================================================
   HOME — CTA CLOSE (home-section-5)
   ============================================================ */
.cta-close {
  background: var(--red);
  padding: 120px 0;
  text-align: center;
  position: relative;
  overflow: hidden;
}
.cta-close-pattern {
  position: absolute;
  inset: -10% 0 -10% 0;
  width: 100%;
  height: 120%;
  opacity: 0.1;
  pointer-events: none;
  animation: drift 30s linear infinite;
}
@keyframes drift {
  0% { transform: translateY(0); }
  100% { transform: translateY(-50%); }
}
.cta-close .eyebrow { color: var(--yellow); margin-bottom: 12px; }
.cta-close h2 {
  color: var(--black);
  font-size: clamp(40px, 7vw, 72px);
  line-height: 1.05;
  margin-bottom: 20px;
  position: relative;
  opacity: 0;
  transform: translateY(-30px);
}
.cta-close.is-in h2 { opacity: 1; transform: translateY(0); transition: transform 280ms linear, opacity 120ms linear; }
.cta-close .sub {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--black);
  opacity: 0.85;
  max-width: 560px;
  margin: 0 auto 32px;
  position: relative;
}
.cta-close-ctas {
  display: inline-flex;
  gap: 24px;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  position: relative;
}

/* ============================================================
   CLASSES PAGE
   ============================================================ */
.page-header-sec {
  background: var(--black);
  padding: 120px 0 80px;
  position: relative;
  overflow: hidden;
}
.ph-grid {
  display: grid;
  grid-template-columns: 65% 35%;
  align-items: center;
  gap: 32px;
}
.ph-text .eyebrow { color: var(--yellow); margin-bottom: 20px; }
.ph-h1 {
  color: var(--chalk);
  font-size: clamp(48px, 10vw, 110px);
  line-height: 0.92;
  letter-spacing: -0.02em;
}
.ph-h1-line {
  display: block;
  opacity: 0;
  transform: translateY(-24px);
}
.ph-h1-line.is-in { opacity: 1; transform: translateY(0); transition: transform 220ms linear, opacity 100ms linear; }
.bleed-word {
  display: inline-block;
  color: var(--red);
  font-size: 1.25em;
  position: relative;
  margin-right: -60px;
  animation-fill-mode: both;
}
.bleed-word.slam { animation: bleedSlam 360ms linear; }
@keyframes bleedSlam {
  0% { transform: translateX(0); }
  35% { transform: translateX(14px); }
  70% { transform: translateX(-2px); }
  100% { transform: translateX(0); }
}

.ph-sub {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--chalk);
  margin-top: 24px;
  max-width: 520px;
  opacity: 0;
}
.ph-sub.is-in { opacity: 1; transition: opacity 400ms 600ms linear; }

.ph-illo { opacity: 0; }
.ph-illo.is-in { opacity: 1; transition: opacity 600ms 400ms linear; }

/* Item grid (classes / instructors / schedule cards) */
.item-grid-sec { background: var(--slab); padding: 80px 0; }
.item-grid-head { margin-bottom: 40px; }
.item-grid-head .eyebrow { color: var(--red); margin-bottom: 12px; }
.item-grid-head h2 { color: var(--chalk); font-size: clamp(32px, 5vw, 56px); }
.item-grid-head .sub { font-family: var(--font-body); color: var(--chalk); opacity: 0.75; margin-top: 16px; }

.cls-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2px;
}
.cls-card {
  background: var(--black);
  border: 1px solid var(--chalk);
  padding: 24px;
  display: flex;
  flex-direction: column;
  min-height: 220px;
  opacity: 0;
  transform: translateY(24px);
}
.cls-card.is-in { opacity: 1; transform: translateY(0); transition: transform 280ms linear, opacity 200ms linear; }
.cls-card h3 {
  color: var(--chalk);
  font-size: 22px;
  margin-bottom: 12px;
  transition: color 80ms linear;
}
.cls-card p {
  font-family: var(--font-body);
  font-size: 14px;
  color: var(--chalk);
  opacity: 0.75;
  flex-grow: 1;
  margin-bottom: 16px;
}
.cls-meta {
  padding-top: 12px;
  border-top: 1px solid rgba(242,242,242,0.2);
  font-family: var(--font-mono);
  font-size: 14px;
  color: var(--yellow);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}
.cls-meta span { margin: 0 4px; color: rgba(242,242,242,0.3); }
.cls-card:hover {
  border: 3px solid var(--red);
  padding: 22px;
}
.cls-card:hover h3 { color: var(--red); }

.item-grid-cta { margin-top: 48px; }

/* Comparison */
.compare-sec { background: var(--black); padding: 0; }
.compare-rule {
  height: 3px;
  background: var(--red);
  width: 0;
}
.compare-rule.is-in { width: 100%; transition: width 320ms linear; }
.compare-inner { padding: 80px 0; }
.compare-head { margin-bottom: 40px; }
.compare-head .eyebrow { color: var(--yellow); margin-bottom: 12px; }
.compare-head h2 { color: var(--chalk); font-size: clamp(36px, 5vw, 64px); }

.compare-table {
  width: 100%;
  border-collapse: collapse;
}
.compare-table th, .compare-table td {
  text-align: left;
  padding: 20px;
  border-bottom: 1px solid rgba(242,242,242,0.15);
}
.compare-table th {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--chalk);
  border-bottom: 2px solid var(--chalk);
}
.compare-table th.col-brutalk { color: var(--red); text-align: center; }
.compare-table th.col-app { color: rgba(242,242,242,0.5); text-align: center; }
.compare-table td.col-brutalk, .compare-table td.col-app {
  text-align: center;
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 20px;
}
.compare-table td.col-brutalk { color: var(--red); }
.compare-table td.col-app { color: rgba(242,242,242,0.4); }
.compare-table tbody tr:nth-child(even) { background: var(--slab); }
.compare-table tbody tr {
  opacity: 0;
  transform: translateY(8px);
  transition: opacity 200ms linear, transform 200ms linear, background-color 80ms linear;
}
.compare-table tbody tr.is-in { opacity: 1; transform: translateY(0); }
.compare-table tbody tr:hover { background: rgba(232,0,13,0.12); }
.feat-title {
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 15px;
  color: var(--chalk);
}
.feat-desc {
  display: block;
  font-family: var(--font-body);
  font-size: 14px;
  color: rgba(242,242,242,0.65);
  font-weight: normal;
  margin-top: 6px;
}

/* FAQ */
.faq-sec { background: var(--slab); padding: 80px 0; position: relative; }
.faq-grid {
  display: grid;
  grid-template-columns: 25% 70%;
  gap: 5%;
  align-items: start;
}
.faq-icons {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.faq-icon-tile {
  width: 64px;
  height: 64px;
  background: var(--black);
  border: 2px solid var(--chalk);
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 28px;
  color: var(--chalk);
  opacity: 0;
  transform: translateX(-24px);
}
.faq-icon-tile.is-in { opacity: 1; transform: translateX(0); transition: transform 240ms linear, opacity 180ms linear; }

.faq-right .eyebrow { color: var(--red); margin-bottom: 12px; }
.faq-right h2 { color: var(--chalk); font-size: clamp(28px, 4.5vw, 48px); margin-bottom: 32px; }
.faq-list { display: flex; flex-direction: column; }
.faq-item {
  border-top: 1px solid rgba(242,242,242,0.2);
  opacity: 0;
  transform: translateY(8px);
}
.faq-item:last-child { border-bottom: 1px solid rgba(242,242,242,0.2); }
.faq-item.is-in { opacity: 1; transform: translateY(0); transition: transform 240ms linear, opacity 180ms linear; }

.faq-q {
  width: 100%;
  background: transparent;
  border: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
  padding: 20px 0;
  text-align: left;
  font-family: var(--font-body);
  font-weight: 700;
  font-size: 16px;
  color: var(--chalk);
  cursor: pointer;
  transition: color 80ms linear;
}
.faq-q:hover { color: var(--blue); }
.faq-toggle {
  font-family: var(--font-head);
  font-weight: 900;
  font-size: 20px;
  color: var(--red);
  display: inline-block;
  transition: transform 120ms linear;
}
.faq-item.is-open .faq-toggle { transform: rotate(45deg); }
.faq-a {
  max-height: 0;
  overflow: hidden;
  font-family: var(--font-body);
  font-size: 15px;
  color: var(--chalk);
  opacity: 0.8;
  line-height: 1.6;
  transition: max-height 140ms linear;
}
.faq-item.is-open .faq-a { max-height: 400px; padding-bottom: 16px; }

.faq-cta { margin-top: 40px; }

/* CTA close (classes / generic) */
.cta-red-sec {
  background: var(--red);
  color: var(--black);
  padding: 80px 0;
  position: relative;
}
.cta-red-sec .eyebrow { color: var(--black); margin-bottom: 16px; }
.cta-red-sec h2 {
  color: var(--black);
  font-size: clamp(40px, 7vw, 80px);
  line-height: 1;
}
.cta-red-sec .sub {
  font-family: var(--font-body);
  font-size: 16px;
  color: var(--black);
  max-width: 480px;
  margin: 20px 0 32px;
}
.cta-red-ctas { display: flex; gap: 16px; flex-wrap: wrap; }

.btn-pulse {
  position: relative;
  animation: pulseBorder 2s ease-in-out infinite;
}
@keyframes pulseBorder {
  0%, 100% { box-shadow: inset 0 0 0 2px rgba(242,242,242,0); }
  50%      { box-shadow: inset 0 0 0 2px rgba(242,242,242,1); }
}

/* ============================================================
   SCHEDULE PAGE
   ============================================================ */
.sched-header { background: var(--black); padding: 80px 0 40px; }
.sched-header-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 20px;
}
.cal-icon { width: 28px; height: 28px; flex-shrink: 0; }
.sched-h1 {
  color: var(--chalk);
  font-size: clamp(40px, 8vw, 96px);
  line-height: 0.95;
  letter-spacing: -0.02em;
  opacity: 0;
  transform: translateX(-40px);
}
.sched-h1.is-in { opacity: 1; transform: translateX(0); transition: transform 320ms linear, opacity 200ms linear; }
.sched-sub {
  font-family: var(--font-body);
